{"file_path":"src/parser.js","content":"/**
 * Parser for the configuration document format described in the task
 * specification: an INI-flavoured, single-line-per-directive dialect with
 * TOML-like values.
 *
 * The document is represented as a tree of tagged nodes:
 *   { kind: 'table', keys: Map, order: string[], path: string[], headerDefined }
 *   { kind: 'aot', tables: Table[], path: string[] }
 *   { kind: 'array', items: Node[] }
 *   { kind: 'string' | 'integer' | 'float' | 'boolean', value }
 *
 * `path` on a table/array-of-tables is the absolute dotted path from the
 * document root, used only to build error messages; output formatting
 * recomputes paths by walking the tree.
 */
import { ParseError } from './errors.js'

function makeTable(path) {
  return { kind: 'table', keys: new Map(), order: [], path, headerDefined: false }
}

// ---- low-level scanning helpers -----------------------------------------

function skipWS(state) {
  const { line } = state
  while (state.pos < line.length && (line[state.pos] === ' ' || line[state.pos] === '\t')) {
    state.pos++
  }
}

function atLineEnd(state) {
  const { line } = state
  if (state.pos >= line.length) return true
  const c = line[state.pos]
  return c === '#' || c === ';'
}

function parseBasicStringRaw(state) {
  const { line, lineNo } = state
  state.pos++ // opening quote
  let out = ''
  for (;;) {
    if (state.pos >= line.length) throw new ParseError(lineNo, 'unterminated string')
    const c = line[state.pos]
    if (c === '"') {
      state.pos++
      return out
    }
    if (c === '\\') {
      state.pos++
      if (state.pos >= line.length) throw new ParseError(lineNo, 'unterminated string')
      const e = line[state.pos]
      switch (e) {
        case '"': out += '"'; state.pos++; break
        case '\\': out += '\\'; state.pos++; break
        case 'n': out += '\n'; state.pos++; break
        case 't': out += '\t'; state.pos++; break
        case 'r': out += '\r'; state.pos++; break
        case '0': out += '\0'; state.pos++; break
        case 'u': {
          const hex = line.slice(state.pos + 1, state.pos + 5)
          if (hex.length !== 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) {
            throw new ParseError(lineNo, 'invalid escape \\u')
          }
          out += String.fromCharCode(parseInt(hex, 16))
          state.pos += 5
          break
        }
        default:
          throw new ParseError(lineNo, `invalid escape \\${e}`)
      }
    } else {
      out += c
      state.pos++
    }
  }
}

function parseLiteralStringRaw(state) {
  const { line, lineNo } = state
  state.pos++ // opening quote
  const start = state.pos
  while (state.pos < line.length && line[state.pos] !== "'") state.pos++
  if (state.pos >= line.length) throw new ParseError(lineNo, 'unterminated string')
  const value = line.slice(start, state.pos)
  state.pos++ // closing quote
  return value
}

const NAME_CHAR = /[A-Za-z0-9_-]/

function parseName(state) {
  skipWS(state)
  if (atLineEnd(state)) throw new ParseError(state.lineNo, 'expected a name')
  const ch = state.line[state.pos]
  if (ch === '"') return parseBasicStringRaw(state)
  if (ch === "'") return parseLiteralStringRaw(state)
  const start = state.pos
  while (state.pos < state.line.length && NAME_CHAR.test(state.line[state.pos])) state.pos++
  if (state.pos === start) throw new ParseError(state.lineNo, 'expected a name')
  return state.line.slice(start, state.pos)
}

function parseDottedName(state) {
  const parts = [parseName(state)]
  for (;;) {
    skipWS(state)
    if (state.pos < state.line.length && state.line[state.pos] === '.') {
      state.pos++
      parts.push(parseName(state))
    } else {
      break
    }
  }
  return parts
}

// ---- values ---------------------------------------------------------------

const NUMBER_RE = /^([+-]?)([0-9]+(?:_[0-9]+)*)(?:\.([0-9]+(?:_[0-9]+)*))?(?:[eE]([+-]?[0-9]+(?:_[0-9]+)*))?$/

function parseBareValue(state) {
  const { line, lineNo } = state
  const start = state.pos
  while (state.pos < line.length) {
    const c = line[state.pos]
    if (c === ' ' || c === '\t' || c === ',' || c === ']' || c === '}') break
    state.pos++
  }
  const token = line.slice(start, state.pos)
  if (token === 'true') return { kind: 'boolean', value: true }
  if (token === 'false') return { kind: 'boolean', value: false }
  const m = NUMBER_RE.exec(token)
  if (m) {
    const isFloat = m[3] !== undefined || m[4] !== undefined
    if (isFloat) {
      return { kind: 'float', value: parseFloat(token.replace(/_/g, '')) }
    }
    const sign = m[1] === '-' ? -1n : 1n
    return { kind: 'integer', value: sign * BigInt(m[2].replace(/_/g, '')) }
  }
  throw new ParseError(lineNo, `invalid value ${token}`)
}

function parseValue(state, basePath) {
  skipWS(state)
  if (atLineEnd(state)) throw new ParseError(state.lineNo, 'expected a value')
  const ch = state.line[state.pos]
  if (ch === ',' || ch === ']' || ch === '}') throw new ParseError(state.lineNo, 'expected a value')
  if (ch === '"') return { kind: 'string', value: parseBasicStringRaw(state) }
  if (ch === "'") return { kind: 'string', value: parseLiteralStringRaw(state) }
  if (ch === '[') return parseArray(state, basePath)
  if (ch === '{') return parseInlineTable(state, basePath)
  return parseBareValue(state)
}

function parseArray(state, basePath) {
  state.pos++ // consume [
  const items = []
  for (;;) {
    skipWS(state)
    if (atLineEnd(state)) throw new ParseError(state.lineNo, 'unterminated array')
    if (state.line[state.pos] === ']') {
      state.pos++
      return { kind: 'array', items }
    }
    items.push(parseValue(state, basePath))
    skipWS(state)
    if (atLineEnd(state)) throw new ParseError(state.lineNo, 'unterminated array')
    const c = state.line[state.pos]
    if (c === ',') {
      state.pos++
      continue
    }
    if (c === ']') {
      state.pos++
      return { kind: 'array', items }
    }
    throw new ParseError(state.lineNo, 'unterminated array')
  }
}

function parseInlineTable(state, basePath) {
  state.pos++ // consume {
  const table = makeTable(basePath)
  skipWS(state)
  if (atLineEnd(state)) throw new ParseError(state.lineNo, 'unterminated inline table')
  if (state.line[state.pos] === '}') {
    state.pos++
    return table
  }
  for (;;) {
    const parts = parseDottedName(state)
    skipWS(state)
    if (atLineEnd(state) || state.line[state.pos] !== '=') {
      throw new ParseError(state.lineNo, 'expected = in an inline table')
    }
    state.pos++ // consume =
    const { parent, last } = resolveTarget(table, parts, state.lineNo)
    checkNotDefined(parent, last, state.lineNo)
    const value = parseValue(state, parent.path.concat([last]))
    parent.keys.set(last, value)
    parent.order.push(last)
    skipWS(state)
    if (atLineEnd(state)) throw new ParseError(state.lineNo, 'unterminated inline table')
    const c = state.line[state.pos]
    if (c === ',') {
      state.pos++
      continue
    }
    if (c === '}') {
      state.pos++
      return table
    }
    throw new ParseError(state.lineNo, 'unterminated inline table')
  }
}

// ---- table/document resolution --------------------------------------------

function walkIntermediate(table, parts, lineNo) {
  let cur = table
  for (const name of parts) {
    const existing = cur.keys.get(name)
    if (existing === undefined) {
      const t = makeTable(cur.path.concat([name]))
      cur.keys.set(name, t)
      cur.order.push(name)
      cur = t
    } else if (existing.kind === 'table') {
      cur = existing
    } else if (existing.kind === 'aot') {
      cur = existing.tables[existing.tables.length - 1]
    } else {
      throw new ParseError(lineNo, `${cur.path.concat([name]).join('.')} is not a table`)
    }
  }
  return cur
}

function resolveTarget(table, parts, lineNo) {
  const allButLast = parts.slice(0, -1)
  const last = parts[parts.length - 1]
  const parent = walkIntermediate(table, allButLast, lineNo)
  return { parent, last }
}

function checkNotDefined(parent, last, lineNo) {
  if (parent.keys.has(last)) {
    throw new ParseError(lineNo, `key ${parent.path.concat([last]).join('.')} is defined twice`)
  }
}

function applyHeader(root, isArray, parts, lineNo) {
  const { parent, last } = resolveTarget(root, parts, lineNo)
  const existing = parent.keys.get(last)
  const fullPath = parent.path.concat([last])
  if (!isArray) {
    if (existing === undefined) {
      const t = makeTable(fullPath)
      t.headerDefined = true
      parent.keys.set(last, t)
      parent.order.push(last)
      return t
    }
    if (existing.kind === 'table') {
      if (existing.headerDefined) {
        throw new ParseError(lineNo, `table ${existing.path.join('.')} is defined twice`)
      }
      existing.headerDefined = true
      return existing
    }
    throw new ParseError(lineNo, `${fullPath.join('.')} is not a table`)
  }
  if (existing === undefined) {
    const aot = { kind: 'aot', tables: [], path: fullPath }
    parent.keys.set(last, aot)
    parent.order.push(last)
    const t = makeTable(fullPath)
    aot.tables.push(t)
    return t
  }
  if (existing.kind === 'aot') {
    const t = makeTable(existing.path)
    existing.tables.push(t)
    return t
  }
  throw new ParseError(lineNo, `${fullPath.join('.')} is not an array of tables`)
}

function parseHeaderLine(line, lineNo, root) {
  let pos = 1
  let isArray = false
  if (line[pos] === '[') {
    isArray = true
    pos++
  }
  const state = { line, pos, lineNo }
  const parts = parseDottedName(state)
  skipWS(state)
  if (atLineEnd(state) || state.line[state.pos] !== ']') {
    throw new ParseError(lineNo, 'unterminated table header')
  }
  state.pos++
  if (isArray) {
    if (state.pos >= line.length || state.line[state.pos] !== ']') {
      throw new ParseError(lineNo, 'unterminated table header')
    }
    state.pos++
  }
  skipWS(state)
  if (!atLineEnd(state)) throw new ParseError(lineNo, 'trailing text after a table header')
  return applyHeader(root, isArray, parts, lineNo)
}

function parseKeyValueLine(line, lineNo, currentTable) {
  const state = { line, pos: 0, lineNo }
  const parts = parseDottedName(state)
  skipWS(state)
  if (atLineEnd(state) || state.line[state.pos] !== '=') {
    throw new ParseError(lineNo, 'expected key = value')
  }
  state.pos++
  const { parent, last } = resolveTarget(currentTable, parts, lineNo)
  checkNotDefined(parent, last, lineNo)
  const value = parseValue(state, parent.path.concat([last]))
  skipWS(state)
  if (!atLineEnd(state)) throw new ParseError(lineNo, 'trailing text after a value')
  parent.keys.set(last, value)
  parent.order.push(last)
}

// ---- entry point ------------------------------------------------------------

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable([])
  let currentTable = root

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    const lineNo = i + 1
    let p = 0
    while (p < line.length && (line[p] === ' ' || line[p] === '\t')) p++
    if (p >= line.length) continue
    if (line[p] === '#' || line[p] === ';') continue
    if (line[p] === '[') {
      currentTable = parseHeaderLine(line, lineNo, root)
    } else {
      parseKeyValueLine(line, lineNo, currentTable)
    }
  }

  return root
}
"}

