  const parts = parseDottedName(state)
  skipWS(state)
  if (atLineEnd(state) || state.line[state.pos] !== '=') {
    throw new ParseError(lineNo, 'expected key = value')
  }
  state.pos++
  const { parent, last } = resolveTarget(currentTable, parts, lineNo)
  checkNotDefined(parent, last, lineNo)
  const value = parseValue(state, parent.path.concat([last]))
  skipWS(state)
  if (!atLineEnd(state)) throw new ParseError(lineNo, 'trailing text after a value')
  parent.keys.set(last, value)
  parent.order.push(last)
}

