  let out = '"'
  for (const ch of str) {
    switch (ch) {
      case '"': out += '\\"'; break
      case '\\': out += '\\\\'; break
      case '\n': out += '\\n'; break
      case '\r': out += '\\r'; break
      case '\t': out += '\\t'; break
      default: {
        const code = ch.codePointAt(0)
        if (code < 0x20) {
          out += '\\u' + code.toString(16).padStart(4, '0')
        } else {
          out += ch
        }
      }
    }
