    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.value.toString()
    case 'float':
      return String(node.value)
    case 'array': {
      if (node.items.length === 0) return '[]'
      const parts = node.items.map((it) => padIn + serializeValue(it, depth + 1))
      return '[\n' + parts.join(',\n') + '\n' + pad + ']'
    }
    case 'aot': {
      if (node.tables.length === 0) return '[]'
      const parts = node.tables.map((t) => padIn + serializeValue(t, depth + 1))
      return '[\n' + parts.join(',\n') + '\n' + pad + ']'
    }
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const parts = keys.map((k) => padIn + jsonEscape(k) + ': ' + serializeValue(node.keys.get(k), depth + 1))
      return '{\n' + parts.join(',\n') + '\n' + pad + '}'
    }
