      visit(node.keys.get(k), path === null ? k : `${path}.${k}`, lines)
    }
  } else if (node.kind === 'aot') {
    node.tables.forEach((t, i) => visit(t, `${path}[${i}]`, lines))
  } else if (node.kind === 'array') {
    node.items.forEach((it, i) => visit(it, `${path}[${i}]`, lines))
  }
}

